const {vec} = NMath;
const {vertices} = await IO.loadMesh("/assets/bunny.obj");

const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    let ans = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    ans = ans.map(x => vec(x.components[2], x.components[0], x.components[1]));
    return ans;
};

function smin(a, b, k = 32) {
    const res = Math.exp(-k * a) + Math.exp(-k * b);
    return -Math.log(res) / k;
}

const distanceToVertices = (point, vectors) => {
    let min = Number.POSITIVE_INFINITY;
    for (let i = 0; i < vectors.length; i++) {
        min = smin(min, point.sub(vectors[i]).length() - 0.05);
    }
    return min;
};

const normalizedVertices = normalizeVectors(vertices.map(vertex => vec(...vertex)));
const trainXs = NArray.range(1024).map(() => vec.random(3).map(value => 2 * value - 1));
const trainYs = trainXs.map(point => distanceToVertices(point, normalizedVertices));

// A positive baseline prevents the Gaussian prediction from approaching zero far from the data.
const baseline = 0.2;
const inputs = trainXs.map(point => point.toArray()).toArray();
const targets = trainYs.map(value => value - baseline).toArray();
let sigma = 0.18;
let lambda = 0.05;
const fit = () => {
    const model = KernelRegression.new(inputs, targets, {sigma, lambda}).fit();
    return model.predictSym().add(Symbolic.real(baseline));
};
const image = IO.sdfViewSymGL(fit(), {aabbClip: {min: [-1.2, -1.2, -1.2], max: [1.2, 1.2, 1.2]}});

let updateTimer;
const update = () => {
    clearTimeout(updateTimer);
    updateTimer = setTimeout(() => image.setExpression(fit()), 150);
};
const ui = IO.UI(
    {type: "canvas", value: () => image},
    {type: "slider", value: () => ({
        title: "Sigma:", min: 0.05, max: 0.3, step: 0.01, value: sigma,
        onChange: value => { sigma = value; update(); },
    })},
    {type: "slider", value: () => ({
        title: "Lambda:", min: 0.05, max: 0.5, step: 0.01, value: lambda,
        onChange: value => { lambda = value; update(); },
    })},
);
ui;
